\documentclass{article}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{tikz}

\begin{document}

\begin{tikzpicture}
\begin{axis}[
    title={粉红色折线图示例},
    xlabel={X轴},
    ylabel={Y轴},
    xmin=0, xmax=10,
    ymin=0, ymax=100,
    xtick={0,2,4,6,8,10},
    ytick={0,20,40,60,80,100},
    legend pos=north west,
    grid=major,
    width=12cm,
    height=8cm,
]

