\addplot [
    color=pink!80!red,
    mark=*,
    line width=1.5pt,
    mark size=3pt,
] coordinates {
    (1, 20)
    (2, 35)
    (3, 45)
    (4, 60)
    (5, 75)
    (6, 50)
    (7, 65)
    (8, 85)
